        <HStack gap={6} wrap>
          {matches.length ? (
            matches.slice(0, 8).map((node) => (
              <Tag
                key={node.id}
                size="small"
                clickable
                pressed={current === node.id}
                onClick={() => focus(node.id)}
              >
                {node.label}
              </Tag>
            ))
          ) : (
            <span style={{ color: "var(--text-secondary-color)" }}>
              {t("noMatch")}
            </span>
          )}
        </HStack>
